import re

_UNITS = {"w": 604800, "d": 86400, "h": 3600, "m": 60, "s": 1}
_ORDER = {unit: index for index, unit in enumerate(_UNITS)}
_PART = re.compile(r"([0-9]+)([wdhms])", re.IGNORECASE)


def parse(text):
    """Parse a duration like '1h30m', '2W 5m' or '45s' into seconds.

    The units are w, d, h, m and s, in upper or lower case. Each unit may appear at most
    once, largest unit first, each with a whole number in front of it. Spaces around
    and between the parts are allowed. Anything else, including an empty string,
    raises ValueError.
    """
    text = text.strip()
    if not text:
        raise ValueError(f"bad duration: {text!r}")
    parts = []
    position = 0
    last_order = -1
    while position < len(text):
        while position < len(text) and text[position].isspace():
            position += 1
        if position >= len(text):
            break
        match = _PART.match(text, position)
        if not match:
            raise ValueError(f"bad duration: {text!r}")
        unit = match.group(2).lower()
        order = _ORDER[unit]
        if order <= last_order:
            raise ValueError(f"bad duration: {text!r}")
        last_order = order
        parts.append((int(match.group(1)), unit))
        position = match.end()
    if not parts:
        raise ValueError(f"bad duration: {text!r}")
    return sum(number * _UNITS[unit] for number, unit in parts)


def format_duration(seconds):
    """Format seconds the way parse() reads them, e.g. 5400 -> '1h30m' and 0 -> '0s'.

    Negative seconds raise ValueError.
    """
    if seconds < 0:
        raise ValueError("negative duration")
    if seconds == 0:
        return "0s"
    out = []
    for unit, size in _UNITS.items():
        if seconds >= size:
            out.append(f"{seconds // size}{unit}")
            seconds %= size
    return "".join(out)

